Architected comprehensive trigger function logic.

Now I need to update the set_activity_code trigger function with the full logic including weekends, company holidays, and rep absences.

Done

Phase 3.1c — Update Submission Status Trigger

Risk Level

MEDIUM — Replacing a live database function. Rollback SQL provided below.

What This Does

The trigger now checks in this order:

Weekend (Fri/Sat) → on_time

Company holiday → on_time

Rep approved absence → on_time

Same day submission → on_time

Within grace period (next working day, skipping weekends + holidays) → on_time

Everything else → late

SQL to Run

CREATE OR REPLACE FUNCTION set_activity_code()
RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
  submitted_date   date;
  activity_dow     int;
  next_working_day date;
  is_excused       boolean := false;
BEGIN
  -- Auto-generate activity code
  IF new.activity_code IS NULL THEN
    new.activity_code := 'ACT-' || lpad(nextval('activity_code_seq')::text, 5, '0');
  END IF;

  -- Set month label
  IF new.activity_date IS NOT NULL THEN
    new.month := to_char(new.activity_date, 'Month YYYY');
  END IF;

  -- Set submission status
  IF new.submission_status IS NULL THEN
    submitted_date := date(new.submitted_at AT TIME ZONE 'Asia/Riyadh');
    activity_dow   := EXTRACT(DOW FROM new.activity_date);
    -- 0=Sun, 1=Mon, 2=Tue, 3=Wed, 4=Thu, 5=Fri, 6=Sat

    -- Step 1: Weekend check (Fri=5, Sat=6)
    IF activity_dow IN (5, 6) THEN
      new.submission_status := 'on_time';

    ELSE
      -- Step 2: Company holiday check
      SELECT EXISTS (
        SELECT 1 FROM company_holidays
        WHERE new.activity_date BETWEEN date_from AND date_to
      ) INTO is_excused;

      -- Step 3: Rep absence check (only if not already excused)
      IF NOT is_excused AND new.rep_id IS NOT NULL THEN
        SELECT EXISTS (
          SELECT 1 FROM rep_absences
          WHERE rep_id = new.rep_id
          AND new.activity_date BETWEEN date_from AND date_to
        ) INTO is_excused;
      END IF;

      -- Step 4: Apply excused status
      IF is_excused THEN
        new.submission_status := 'on_time';

      -- Step 5: Same day submission
      ELSIF submitted_date = new.activity_date THEN
        new.submission_status := 'on_time';

      -- Step 6: Grace period check
      ELSIF submitted_date > new.activity_date THEN
        -- Calculate next working day after activity_date
        -- skipping weekends and company holidays
        next_working_day := new.activity_date + 1;

        LOOP
          -- Skip Friday and Saturday
          IF EXTRACT(DOW FROM next_working_day) IN (5, 6) THEN
            next_working_day := next_working_day + 1;
            CONTINUE;
          END IF;

          -- Skip company holidays
          IF EXISTS (
            SELECT 1 FROM company_holidays
            WHERE next_working_day BETWEEN date_from AND date_to
          ) THEN
            next_working_day := next_working_day + 1;
            CONTINUE;
          END IF;

          -- Found next working day
          EXIT;
        END LOOP;

        IF submitted_date <= next_working_day THEN
          new.submission_status := 'on_time';
        ELSE
          new.submission_status := 'late';
        END IF;

      END IF;
    END IF;
  END IF;

  RETURN new;
END;
$$;

