Phase 3.1d — Notification Function for Expired Grace Periods

Goal

Create a database function that checks for reps who missed their grace period and fires notifications to both the rep and the manager.

Risk Level

SAFE — Creating a new function. Nothing existing is touched.

How It Works

This function will be called from the manager dashboard when it loads. It checks yesterday's working day and finds any active reps who have no activity submitted for that day and are not excused. It then inserts notifications for both the rep and all managers — but only once (it won't fire duplicate notifications if already sent).

SQL to Run

CREATE OR REPLACE FUNCTION check_missing_submissions()
RETURNS void LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE
  check_date       date;
  check_dow        int;
  prev_working_day date;
  rep_record       RECORD;
  manager_record   RECORD;
  already_notified boolean;
  is_excused       boolean;
BEGIN
  -- Find the most recent working day to check
  -- Start from yesterday and go back until we find a working day
  prev_working_day := CURRENT_DATE - 1;

  LOOP
    check_dow := EXTRACT(DOW FROM prev_working_day);

    -- Skip weekends
    IF check_dow IN (5, 6) THEN
      prev_working_day := prev_working_day - 1;
      CONTINUE;
    END IF;

    -- Skip company holidays
    IF EXISTS (
      SELECT 1 FROM company_holidays
      WHERE prev_working_day BETWEEN date_from AND date_to
    ) THEN
      prev_working_day := prev_working_day - 1;
      CONTINUE;
    END IF;

    -- Found last working day
    EXIT;
  END LOOP;

  -- Loop through all active reps and marketing users
  FOR rep_record IN
    SELECT id, name
    FROM reps
    WHERE status = 'active'
    AND role IN ('rep', 'marketing')
  LOOP
    -- Check if this rep is excused for that day
    SELECT EXISTS (
      SELECT 1 FROM rep_absences
      WHERE rep_id = rep_record.id
      AND prev_working_day BETWEEN date_from AND date_to
    ) INTO is_excused;

    -- Skip excused reps
    IF is_excused THEN
      CONTINUE;
    END IF;

    -- Check if rep has any activity for that day
    IF NOT EXISTS (
      SELECT 1 FROM activities
      WHERE rep_id = rep_record.id
      AND activity_date = prev_working_day
    ) THEN
      -- Check if we already sent this notification today
      SELECT EXISTS (
        SELECT 1 FROM notifications
        WHERE recipient_id = rep_record.id
        AND type = 'missing_submission'
        AND created_at::date = CURRENT_DATE
        AND body LIKE '%' || prev_working_day::text || '%'
      ) INTO already_notified;

      IF NOT already_notified THEN
        -- Notify the rep
        INSERT INTO notifications (
          recipient_id, type, title, body, entity_type
        ) VALUES (
          rep_record.id,
          'missing_submission',
          'Missing Daily Report',
          'You have not submitted your daily report for ' || 
            to_char(prev_working_day, 'DD Mon YYYY') || 
            '. Please submit it as soon as possible or ask your manager to record an absence.',
          'rep'
        );

        -- Notify all managers
        FOR manager_record IN
          SELECT id FROM reps
          WHERE status = 'active'
          AND role = 'manager'
        LOOP
          -- Check if manager was already notified today for this rep
          SELECT EXISTS (
            SELECT 1 FROM notifications
            WHERE recipient_id = manager_record.id
            AND type = 'missing_submission'
            AND created_at::date = CURRENT_DATE
            AND body LIKE '%' || rep_record.name || '%'
            AND body LIKE '%' || prev_working_day::text || '%'
          ) INTO already_notified;

          IF NOT already_notified THEN
            INSERT INTO notifications (
              recipient_id, type, title, body, entity_type
            ) VALUES (
              manager_record.id,
              'missing_submission',
              'Missing Report: ' || rep_record.name,
              rep_record.name || ' has not submitted their daily report for ' ||
                to_char(prev_working_day, 'DD Mon YYYY') || '.',
              'rep'
            );
          END IF;
        END LOOP;

      END IF;
    END IF;
  END LOOP;
END;
$$;

