Phase 4.5g — Drop and Recreate the RPC

PostgreSQL won't let us rename a parameter in place. We need to drop the function first then recreate it.

Run These in Order

Query 1 — Drop the existing function:

DROP FUNCTION IF EXISTS create_project_with_rep(uuid,text,text,text,numeric,date,text,uuid,uuid);

Query 2 — Recreate with new parameter name:

CREATE OR REPLACE FUNCTION create_project_with_rep(
  p_customer_id    uuid,
  p_project_name   text,
  p_city           text,
  p_stage          text,
  p_quoted_sqm     numeric,
  p_project_date   date,
  p_notes          text,
  p_contact_id     uuid,
  p_rep_id         uuid
) RETURNS uuid LANGUAGE plpgsql AS $$
DECLARE
  v_project_id   uuid;
  v_company_name text;
BEGIN
  SELECT company_name INTO v_company_name
  FROM companies WHERE id = p_customer_id;

  INSERT INTO projects (
    customer_id, company_name, project_name, city, stage,
    quoted_sqm, project_date, notes, contact_id, assigned_rep_id
  ) VALUES (
    p_customer_id, v_company_name, p_project_name, p_city, p_stage,
    p_quoted_sqm, COALESCE(p_project_date, CURRENT_DATE), p_notes,
    p_contact_id, p_rep_id
  ) RETURNING id INTO v_project_id;

  IF p_rep_id IS NOT NULL THEN
    INSERT INTO project_reps (project_id, rep_id, role, assigned_by)
    VALUES (v_project_id, p_rep_id, 'primary', p_rep_id);
  END IF;

  RETURN v_project_id;
END;
$$;

