Phase 4.5j — Create the History Trigger

SQL to Run

-- Trigger function that logs project changes
CREATE OR REPLACE FUNCTION log_project_changes()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE
  v_rep_id uuid;
BEGIN
  -- Get the rep making the change
  SELECT id INTO v_rep_id FROM reps WHERE auth_user_id = auth.uid() LIMIT 1;

  -- Log stage changes
  IF OLD.stage IS DISTINCT FROM NEW.stage THEN
    INSERT INTO project_history (project_id, changed_by, field_name, old_value, new_value)
    VALUES (NEW.id, v_rep_id, 'stage', OLD.stage, NEW.stage);
  END IF;

  -- Log quoted SQM changes
  IF OLD.quoted_sqm IS DISTINCT FROM NEW.quoted_sqm THEN
    INSERT INTO project_history (project_id, changed_by, field_name, old_value, new_value)
    VALUES (NEW.id, v_rep_id, 'quoted_sqm', OLD.quoted_sqm::text, NEW.quoted_sqm::text);
  END IF;

  -- Log loss reason changes
  IF OLD.loss_reason IS DISTINCT FROM NEW.loss_reason AND NEW.loss_reason IS NOT NULL THEN
    INSERT INTO project_history (project_id, changed_by, field_name, old_value, new_value)
    VALUES (NEW.id, v_rep_id, 'loss_reason', OLD.loss_reason, NEW.loss_reason);
  END IF;

  -- Log rep assignment changes
  IF OLD.assigned_rep_id IS DISTINCT FROM NEW.assigned_rep_id THEN
    INSERT INTO project_history (project_id, changed_by, field_name, old_value, new_value)
    VALUES (NEW.id, v_rep_id, 'assigned_rep',
      (SELECT name FROM reps WHERE id = OLD.assigned_rep_id),
      (SELECT name FROM reps WHERE id = NEW.assigned_rep_id)
    );
  END IF;

  RETURN NEW;
END;
$$;

-- Attach trigger to projects table
DROP TRIGGER IF EXISTS trg_project_history ON projects;
CREATE TRIGGER trg_project_history
  AFTER UPDATE ON projects
  FOR EACH ROW EXECUTE FUNCTION log_project_changes();

Verify

