Three separate root causes. All fixable with SQL — no code changes needed.

Root Cause Diagnosis

Companies INSERT failing — there is no INSERT policy for reps on company_reps. The rep can insert into companies but then the second insert into company_reps is blocked.

project_reps INSERT failing — create_project_with_rep runs as the calling user, not as postgres. There is no INSERT policy for reps on project_reps, so it fails.

Project dropdown empty — super_admin is not included in the projects_manager policy, so the projects query returns nothing for Jerom.

Fix — Run all of this in Supabase SQL Editor

-- ─── 1. Allow reps to insert into company_reps (when registering a company) ───
DROP POLICY IF EXISTS "company_reps_rep_insert" ON company_reps;
CREATE POLICY "company_reps_rep_insert" ON company_reps FOR INSERT WITH CHECK (
  current_user_role() IN ('rep','marketing','super_admin')
);

-- ─── 2. Make create_project_with_rep bypass RLS (SECURITY DEFINER) ───
-- This is the correct pattern: reps call a controlled function, 
-- the function inserts into project_reps as postgres, not as the rep.
CREATE OR REPLACE FUNCTION create_project_with_rep(
  p_customer_id    uuid,
  p_project_name   text,
  p_city           text,
  p_stage          text,
  p_quoted_sqm     numeric,
  p_project_date   date,
  p_notes          text,
  p_contact_id     uuid,
  p_rep_id         uuid
) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE
  v_project_id   uuid;
  v_company_name text;
BEGIN
  SELECT company_name INTO v_company_name FROM companies WHERE id = p_customer_id;

  INSERT INTO projects (
    customer_id, company_name, project_name, city, stage,
    quoted_sqm, project_date, notes, contact_id, assigned_rep_id
  ) VALUES (
    p_customer_id, v_company_name, p_project_name, p_city, p_stage,
    p_quoted_sqm, p_project_date, p_notes, p_contact_id, p_rep_id
  ) RETURNING id INTO v_project_id;

  IF p_rep_id IS NOT NULL THEN
    INSERT INTO project_reps (project_id, rep_id, role, assigned_by)
    VALUES (v_project_id, p_rep_id, 'primary', p_rep_id);
  END IF;

  RETURN v_project_id;
END;
$$;

-- ─── 3. Add super_admin to all manager-level policies ───
DROP POLICY IF EXISTS "companies_manager"          ON companies;
DROP POLICY IF EXISTS "companies_coordinator_read" ON companies;
DROP POLICY IF EXISTS "companies_rep_insert"       ON companies;
DROP POLICY IF EXISTS "companies_rep_update"       ON companies;

CREATE POLICY "companies_manager" ON companies FOR ALL
  USING (current_user_role() IN ('manager','sales_coordinator','super_admin'));

CREATE POLICY "companies_rep_read" ON companies FOR SELECT
  USING (
    current_user_role() IN ('rep','marketing') AND EXISTS (
      SELECT 1 FROM company_reps
