-- Fix 2: Create a SECURITY DEFINER function for company + company_reps insert
-- Same pattern as create_project_with_rep — bypasses RLS cleanly
CREATE OR REPLACE FUNCTION create_company_with_rep(
  p_company_name  text,
  p_company_type  text,
  p_region        text,
  p_source        text,
  p_source_detail text,
  p_notes         text,
  p_rep_id        uuid
) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE
  v_company_id uuid;
BEGIN
  INSERT INTO companies (
    company_name, company_type, region, source,
    source_detail, notes, status, primary_rep_id
  ) VALUES (
    p_company_name,
    NULLIF(p_company_type, ''),
    NULLIF(p_region, ''),
    NULLIF(p_source, ''),
    NULLIF(p_source_detail, ''),
    NULLIF(p_notes, ''),
    'active',
    p_rep_id
  ) RETURNING id INTO v_company_id;

  INSERT INTO company_reps (company_id, rep_id, role, assigned_by)
  VALUES (v_company_id, p_rep_id, 'primary', p_rep_id);

  RETURN v_company_id;
END;
$$;

